messages.content:
Tool response:
Tool: search_tutors
Description: Search tutors based on subject ID, minimum average rating, minimum number of reviews,
and availability for group sessions on weekends within the next 14 days.
Parameters:
    {
      "type": "object",
      "properties": {
        "subject_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter tutors by subject ID",
          "title": "Subject Id"
        },
        "min_rating": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum average rating (e.g., 4.0)",
          "title": "Min Rating"
        },
        "min_reviews": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum number of reviews required",
          "title": "Min Reviews"
        },
        "start_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Start date for availability filter (ISO 8601 format)",
          "title": "Start Date"
        },
        "end_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "End date for availability filter (ISO 8601 format)",
          "title": "End Date"
        },
        "max_students": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of students allowed in session (default 4)",
          "default": 4,
          "title": "Max Students"
        },
        "is_group_session": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Whether session must be a group session (default true)",
          "default": true,
          "title": "Is Group Session"
        }
      },
      "required": []
    }
